-- ============================================================
-- SEED EXT 2: Módulo 08 — Past Perfect (exercícios 71-175)
-- Novos tópicos: Past Perfect Continuous, passive past perfect,
-- reported speech backshift, narrative in academic texts,
-- TOEFL Reading/Writing/Speaking
-- ============================================================
DO $$
DECLARE cid TEXT;
BEGIN
  SELECT id INTO cid FROM contents WHERE id = 'past-perfect';
  IF cid IS NULL THEN RAISE EXCEPTION 'Módulo past-perfect não encontrado'; END IF;

  INSERT INTO exercises (content_id, block_number, exercise_number, type, question, answer, options, explanation, difficulty) VALUES

  -- BLOCK 11: Past Perfect Continuous (had been + -ing)
  (cid,11,71,'gap_fill','The researchers ___ (analyze) the data for six months when a critical flaw was discovered.','had been analyzing',NULL,'Past perfect continuous: had been + -ing for an ongoing action interrupted in the past.','hard'),
  (cid,11,72,'multiple_choice','Choose the correct Past Perfect Continuous:','By the time she defended, she had been working on her dissertation for four years.','["By the time she defended, she has been working on her dissertation for four years.","By the time she defended, she was working on her dissertation for four years.","By the time she defended, she had been working on her dissertation for four years.","By the time she defended, she had worked on her dissertation for four years (focuses on result)."]','Had been + -ing + for = ongoing process up to a past point.','hard'),
  (cid,11,73,'gap_fill','He looked exhausted because he ___ (work) on the problem all night.','had been working',NULL,'Past perfect continuous for sustained past activity with visible present result.','medium'),
  (cid,11,74,'multiple_choice','What is the difference between "She had read the report" and "She had been reading the report"?','Had read = completed before a past event. Had been reading = she was in the process of reading (duration/ongoing activity).','["They are identical","Had read is formal; had been reading is informal","Had read = completed before a past event. Had been reading = she was in the process of reading (duration/ongoing activity).","Had been reading suggests she never finished"]','Past perfect simple = result/completion. Past perfect continuous = process/duration.','hard'),
  (cid,11,75,'gap_fill','The lab equipment malfunctioned because it ___ (run) without maintenance for two years.','had been running',NULL,'Had been + -ing for sustained activity that led to a past consequence.','hard'),
  (cid,11,76,'multiple_choice','Which sentence uses Past Perfect Continuous CORRECTLY?','Scientists had been warning about climate change for decades before governments acted.','["Scientists had warned about climate change for decades before governments acted (also acceptable — focuses on result).","Scientists had been warned about climate change for decades (passive — wrong: scientists do the warning).","Scientists had been warning about climate change for decades before governments acted.","Scientists were warning about climate change for decades before governments acted."]','Had been + -ing = sustained advocacy over a long period before a past turning point.','hard'),
  (cid,11,77,'gap_fill','The team celebrated after completing the project — they ___ (plan) it for 18 months.','had been planning',NULL,'"Had been planning" for the sustained process that preceded completion.','medium'),

  -- BLOCK 12: passive past perfect (had been + past participle)
  (cid,12,78,'gap_fill','The data ___ (process/passive) before the analysis began.','had been processed',NULL,'Past perfect passive: had been + past participle.','hard'),
  (cid,12,79,'multiple_choice','Which is the correct past perfect passive?','By the time the study was published, the findings had been verified by three independent teams.','["The findings has been verified by three teams before publication.","By the time the study was published, the findings had been verified by three independent teams.","The findings had been verifying by three teams before publication.","The findings have been verified before publication."]','Had been + past participle = past perfect passive.','hard'),
  (cid,12,80,'gap_fill','The participants ___ (inform/passive) about the risks before they consented to the study.','had been informed',NULL,'"Had been informed" = passive past perfect for earlier ethical procedure.','hard'),
  (cid,12,81,'multiple_choice','Convert to past perfect passive: "Researchers had collected the samples before the lab closed."','The samples had been collected before the lab closed.','["The samples were collected before the lab closed.","The samples had collected before the lab closed.","The samples had been collected before the lab closed.","The samples have been collected before the lab closed."]','Had been + past participle for passive past perfect.','medium'),
  (cid,12,82,'gap_fill','By the time the new director arrived, the budget ___ (allocate/passive) for the entire year.','had been allocated',NULL,'Had been + past participle for completed passive action before a past event.','hard'),
  (cid,12,83,'multiple_choice','Why is passive past perfect used in academic writing?','To emphasize what was completed (and by what process) before a key past moment, without naming who did it.','["It sounds more intelligent","To emphasize what was completed (and by what process) before a key past moment, without naming who did it.","It is shorter than the active form","It is grammatically required in academic writing"]','Passive removes focus from agent, keeps focus on the completed procedure/result.','hard'),

  -- BLOCK 13: reported speech — backshift to past perfect
  (cid,13,84,'gap_fill','Direct: "We have completed the trial." → Reported: She announced that they ___ the trial.','had completed',NULL,'Present perfect → past perfect in reported speech.','hard'),
  (cid,13,85,'multiple_choice','Which correctly converts to reported speech with past perfect backshift?','He told us that the committee had approved the proposal the previous week.','["He told us that the committee has approved the proposal last week.","He told us that the committee approved the proposal last week (past simple — also acceptable).","He told us that the committee had approved the proposal the previous week.","He said the committee will approve the proposal last week."]','Past simple / present perfect → past perfect in reported speech.','hard'),
  (cid,13,86,'gap_fill','Direct: "I finished the analysis yesterday." → Reported: She said she ___ the analysis the day before.','had finished',NULL,'Past simple → past perfect in reported speech + time expression change.','hard'),
  (cid,13,87,'multiple_choice','Why does past simple backshift to past perfect in reported speech?','To show that the original action occurred even earlier than the reporting moment.','["Because past perfect is always used in formal writing","To show that the original action occurred even earlier than the reporting moment.","Because past simple cannot appear in reported speech","Because it sounds more sophisticated"]','Temporal distancing: the original event was in the past relative to the reporting time.','hard'),
  (cid,13,88,'gap_fill','Direct: "I had never seen results like these before." → Reported: He admitted that he ___ never ___ results like those before.','had / seen',NULL,'Past perfect remains past perfect in reported speech (no further backshift possible).','hard'),

  -- BLOCK 14: academic narrative and historical sequence
  (cid,14,89,'multiple_choice','[Academic] Which sentence uses past perfect most effectively in a research narrative?','By the time the clinical trial began, the researchers had already completed two years of laboratory testing.','["By the time the clinical trial began, the researchers already completed two years of testing.","By the time the clinical trial began, the researchers had already completed two years of laboratory testing.","By the time the clinical trial begins, the researchers had completed two years of testing.","By the time the clinical trial began, the researchers have completed two years of testing."]','Had + already + past participle with "by the time" = correct academic past perfect narrative.','hard'),
  (cid,14,90,'gap_fill','Penicillin ___ (be/discover) before World War II, but mass production only became possible during the war itself.','had been discovered',NULL,'Past perfect passive for a discovery preceding the war.','hard'),
  (cid,14,91,'multiple_choice','In an academic paper on historical events, which tense is used to describe an event that preceded the main event being discussed?','Past perfect','["Present perfect","Past simple","Past perfect","Present simple"]','Past perfect = the tense of "the event before the event" in narrative.','easy'),
  (cid,14,92,'gap_fill','By the time the Industrial Revolution reached its peak, urbanization ___ (transform) British society beyond recognition.','had transformed',NULL,'"By the time + past simple" → past perfect for prior transformation.','hard'),
  (cid,14,93,'multiple_choice','Which sentence is INCORRECT in academic historical narrative?','By 1905, Einstein had publish his special theory of relativity.','["By 1905, Einstein had published his special theory of relativity.","Before the war ended, both sides had suffered catastrophic losses.","By the time Columbus arrived, indigenous civilizations had flourished for millennia.","By 1905, Einstein had publish his special theory of relativity."]','"Had publish" is wrong — past participle required: "had published."','medium'),
  (cid,14,94,'gap_fill','___ the project ___ (complete/passive) when the funding agency withdrew support.','Had / been completed / hadn''t',NULL,'Past perfect passive question or negative for academic narrative.','hard'),

  -- BLOCK 15: TOEFL Reading
  (cid,15,95,'multiple_choice','[TOEFL Reading] "By the time antibiotics became widely available, tuberculosis had claimed millions of lives." The past perfect here indicates:','Deaths occurred before the widespread availability of antibiotics.','["Antibiotics and tuberculosis deaths happened simultaneously","Deaths occurred before the widespread availability of antibiotics.","Antibiotics were not effective against tuberculosis","Deaths occurred after antibiotics became available"]','Had claimed = earlier event (deaths) before the later event (antibiotics available).','easy'),
  (cid,15,96,'gap_fill','[TOEFL Reading] "When Darwin returned from the Galápagos, he ___ (observe) finches that would inspire his theory." Best form?','had observed',NULL,'Had observed = earlier observation before returning and formulating the theory.','medium'),
  (cid,15,97,'multiple_choice','[TOEFL Reading] "The ancient Romans had developed sophisticated water systems long before medieval European cities had access to clean water." The past perfect emphasizes:','Roman infrastructure pre-dated medieval European sanitation by many centuries.','["Roman and medieval water systems developed at the same time","Medieval water systems were better than Roman ones","Roman infrastructure pre-dated medieval European sanitation by many centuries.","The medieval period came before the Roman period"]','Had developed = earlier (Roman) before the later (medieval) reference point.','medium'),
  (cid,15,98,'gap_fill','[TOEFL Reading] "The researchers noted that the anomaly ___ (appear) in earlier datasets but ___ (overlook/passive) by previous teams." Best forms?','had appeared / had been overlooked',NULL,'Two past perfect verbs: earlier events before the main past research event.','hard'),
  (cid,15,99,'multiple_choice','[TOEFL Reading] "Prior to the invention of the steam engine, most manufacturing had relied on human or animal labor." This past perfect implies:','Human/animal labor was the norm in manufacturing BEFORE steam engines changed everything.','["Steam engines existed before the sentence implies","Human labor continued after the steam engine","Human/animal labor was the norm in manufacturing BEFORE steam engines changed everything.","Manufacturing did not exist before steam engines"]','"Had relied" = past state that existed before the pivot event (steam engine invention).','medium'),

  -- BLOCK 16: TOEFL Listening
  (cid,16,100,'multiple_choice','[TOEFL Listening] A professor says: "By the time the policy was reversed, significant damage had already been done." A student paraphrases: "The damage happened after the policy reversal." Is this correct?','No — the damage happened BEFORE the policy was reversed.','["Yes — the sentence supports this","No — the damage happened BEFORE the policy was reversed.","Yes — ''had been done'' = future","No — the sentence does not mention damage"]','Had been done = earlier event. Was reversed = later event.','hard'),
  (cid,16,101,'gap_fill','[TOEFL Listening] A professor reports: "She noted that her team ___ (collect) three years of data before developing their model." Best form?','had collected',NULL,'Reported speech: had collected = past perfect for the earlier research phase.','medium'),
  (cid,16,102,'multiple_choice','[TOEFL Listening] "The speaker explained that the theory had been proposed years earlier but had been widely dismissed at the time." This describes:','An earlier intellectual contribution that was not initially accepted.','["A new theory being introduced for the first time","A theory that was immediately adopted","An earlier intellectual contribution that was not initially accepted.","A theory that the speaker invented"]','Had been proposed + had been dismissed = two past perfect events (earlier than the past narrative).','hard'),

  -- BLOCK 17: TOEFL Speaking production
  (cid,17,103,'production','[TOEFL Speaking — 45s] You read about a scientific discovery that built on decades of prior research. Describe the sequence of events using past perfect (×2), past simple (×2), and past perfect continuous (×1).','',NULL,'By the time the team published their discovery, they had been studying the protein for nearly a decade. Earlier researchers had identified a similar structure in 2005, but its function remained unclear. The team refined the earlier model and tested it extensively. Finally, in 2023, they published a paper that overturned the dominant theory.','hard'),
  (cid,17,104,'production','[TOEFL Speaking — 45s] A professor claims that many great scientific discoveries were made by researchers who had previously failed. Describe one example using: had failed, had spent, had been working, before finally (past simple).','',NULL,'Alexander Fleming had been working in bacteriology for years before his accidental discovery of penicillin. He had previously failed to find a reliable antibacterial agent. He had spent countless hours testing compounds without success. Before finally noticing the mold that killed the bacteria in his petri dish, he had nearly abandoned his research direction entirely.','hard'),

  -- BLOCK 18: TOEFL Writing production
  (cid,18,105,'production','[TOEFL Writing] Write a 5-sentence paragraph about the history of space exploration using: had been (passive PP continuous or simple), had launched, had been developing, by the time, had proved.','',NULL,'By the time Neil Armstrong set foot on the Moon in 1969, NASA had been developing rocket technology for over a decade. The Soviet Union had launched the first satellite, Sputnik, in 1957, intensifying the Space Race. American engineers had been working around the clock to meet Kennedy''s deadline. The Apollo program had proved that human ingenuity could overcome even the most daunting technical challenges. By the time the program ended, it had demonstrated capabilities that had seemed impossible just years earlier.','hard'),
  (cid,18,106,'production','[TOEFL Writing — Error Correction] Fix all past perfect errors: "By the time the results arrived, the team already analyzed them. She said she has completed the survey the day before. The vaccine had be tested before approval. When I arrived, the lecture already started."','',NULL,'had already analyzed (not ''already analyzed'' without had); had completed (not ''has completed'' in reported speech backshift); had been tested (had be → had been); had already started (when + past perfect for the earlier event).','hard'),
  (cid,18,107,'production','[TOEFL Writing — 200 words] Write a TOEFL-style paragraph on: "How did prior scientific work lay the foundation for the Human Genome Project?" Use: past perfect (×3), past perfect continuous (×1), past perfect passive (×1), and "by the time" (×1). Underline each past perfect structure.','',NULL,'By the time the Human Genome Project officially launched in 1990, scientists had already developed the core sequencing technologies that would make it possible. Researchers had been mapping smaller genomes — including that of bacteria and yeast — for over a decade, gradually refining the techniques needed to handle the vast complexity of human DNA. The double helix structure of DNA had been discovered by Watson and Crick in 1953, providing the theoretical foundation without which the project could not have been conceived. Over the following decades, biochemists had developed increasingly powerful polymerase chain reaction (PCR) methods, enabling rapid amplification of genetic material. These accumulated advances meant that, by the late 1980s, the scientific community had built sufficient knowledge and infrastructure to attempt the monumental task of sequencing all 3 billion base pairs of the human genome. The project, which ultimately succeeded in 2003, would not have been possible without this rich legacy of accumulated biological knowledge.','hard')

  ON CONFLICT (content_id, block_number, exercise_number) DO NOTHING;
END $$;
